class Solution {
    public int minJumps(int[] arr){
        Map<Integer,List<Integer>> indices=new HashMap<>();
        for(int i=0;i<arr.length;i++)indices.computeIfAbsent(arr[i],key->new ArrayList<>()).add(i);
        Queue<int[]> queue=new ArrayDeque<>();
        boolean[] seen=new boolean[arr.length];
        queue.offer(new int[]{
            0,0
        });
        seen[0]=true;
        while(!queue.isEmpty()){
            int[] state=queue.poll();
            int index=state[0];
            if(index==arr.length-1)return state[1];
            List<Integer> next=new ArrayList<>();
            if(index>0)next.add(index-1);
            if(index+1<arr.length)next.add(index+1);
            next.addAll(indices.getOrDefault(arr[index],Collections.emptyList()));
            for(int value:next)if(!seen[value]){
                seen[value]=true;
                queue.offer(new int[]{
                    value,state[1]+1
                });
            }
            indices.remove(arr[index]);
        }
        return -1;
    }
}

